#!/usr/bin/env Rscript
source(file.path(dirname(normalizePath(sub("^--file=", "", commandArgs(FALSE)[grep("^--file=", commandArgs(FALSE))]))), "dv_shared.R"))
dv_require(c("limma","statmod","digest"));hash<-dv_assert_candidate_hash();stage<-"D07_site_robustness";outdir<-dv_stage_dir(stage)
meta<-dv_assignment("Discovery");ef<-file.path(dv_stage_dir("D01_discovery_eligibility"),"D01_discovery_eligible_expression.csv.gz");expr0<-dv_read_expression(ef,meta$UniqueSampleID,TRUE);lock<-dv_read_csv(file.path(dv_stage_dir("D03_candidate_lock"),"D03_locked_candidates.csv"),c("PG.ProteinGroups","log2FC"));expr<-expr0[match(lock$PG.ProteinGroups,rownames(expr0)),,drop=FALSE]
composition<-as.data.frame(table(Site=factor(meta$group,levels=DV_SITES),Dose=factor(meta$TREAT1_clean,levels=DV_DOSE))); summaries<-do.call(rbind,lapply(DV_SITES,function(s)do.call(rbind,lapply(DV_DOSE,function(g){ix<-meta$group==s&meta$TREAT1_clean==g;data.frame(PG.ProteinGroups=rownames(expr),Site=s,Dose=g,N_total=sum(ix),N_observed=rowSums(is.finite(expr[,ix,drop=FALSE])),Median_abundance=apply(expr[,ix,drop=FALSE],1,function(v)if(any(is.finite(v)))median(v,na.rm=TRUE)else NA_real_))}))))
major<-names(which(table(meta$group)>=20)); loo<-list()
for(s in major){keep<-meta$group!=s;m<-meta[keep,,drop=FALSE];x<-expr[,keep,drop=FALSE];d<-dv_design(m);if(qr(d)$rank<ncol(d)||!all(DV_DOSE%in%m$TREAT1_clean)){z<-data.frame(PG.ProteinGroups=rownames(expr),Site_removed=s,Model_status="NON_ESTIMABLE")}else{z<-dv_fit(x,d,dv_primary_contrast(d),family_n=nrow(x));z$Site_removed<-s;z$Primary_log2FC<-lock$log2FC[match(z$PG.ProteinGroups,lock$PG.ProteinGroups)];z$Direction_stable<-sign(z$log2FC)==sign(z$Primary_log2FC);z$Delta_log2FC<-z$log2FC-z$Primary_log2FC};loo[[s]]<-z}
paths<-file.path(outdir,c("D07_site_dose_composition.csv","D07_candidate_site_summaries.csv","D07_leave_one_major_site_out.csv","D07_manifest.csv"));dv_no_overwrite(paths);dv_write(composition,paths[1]);dv_write(summaries,paths[2]);dv_write(do.call(rbind,loo),paths[3]);dv_write(dv_manifest(stage,c(ef,file.path(dv_stage_dir("D03_candidate_lock"),"D03_locked_candidates.csv")),paths[1:3],list(candidate_hash=hash,major_site_rule="Discovery n >= 20",candidate_membership="UNCHANGED")),paths[4])
